require_once __DIR__.'/../config/app.php';require_admin();$id=(int)($_GET['id']??0);
if(is_post()&&($_POST['action']??'')==='status'){verify_csrf();$new=$_POST['order_status']??'';$notes=trim($_POST['notes']??'');$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT * FROM orders WHERE id=? FOR UPDATE');$s->execute([$id]);$current=$s->fetch();if(!$current)throw new RuntimeException('Pesanan tidak ditemukan.');if(!valid_order_transition($current['order_status'],$new,$current['fulfillment_method']))throw new RuntimeException('Transisi status tidak diizinkan.');if($new==='cancelled'&&!$current['stock_restored_at']){$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$id]);foreach($items->fetchAll() as $item){if(!$item['product_id'])continue;$p=$pdo->prepare('SELECT stock FROM products WHERE id=? FOR UPDATE');$p->execute([$item['product_id']]);$before=(int)$p->fetchColumn();$after=$before+(int)$item['quantity'];$pdo->prepare('UPDATE products SET stock=? WHERE id=?')->execute([$after,$item['product_id']]);$pdo->prepare("INSERT INTO stock_movements(product_id,user_id,order_id,movement_type,quantity,stock_before,stock_after,notes) VALUES(?,?,?,'return',?,?,?,?)")->execute([$item['product_id'],current_user()['id'],$id,$item['quantity'],$before,$after,'Pesanan dibatalkan admin']);}$pdo->prepare('UPDATE orders SET stock_restored_at=NOW() WHERE id=?')->execute([$id]);}$pdo->prepare('UPDATE orders SET order_status=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO order_status_histories(order_id,changed_by,old_status,new_status,notes) VALUES(?,?,?,?,?)')->execute([$id,current_user()['id'],$current['order_status'],$new,$notes]);$pdo->commit();notify_order_status_changed($id);flash('success','Status pesanan diperbarui.');}catch(Throwable $e){$pdo->rollBack();flash('danger',$e->getMessage());}redirect('admin/order-detail.php?id='.$id);}
$stmt=db()->prepare('SELECT o.*,u.name buyer_name,u.email,p.id payment_id,p.proof_image,b.bank_name,b.account_number,b.account_holder FROM orders o JOIN users u ON u.id=o.user_id LEFT JOIN payments p ON p.order_id=o.id LEFT JOIN bank_accounts b ON b.id=p.bank_account_id WHERE o.id=?');$stmt->execute([$id]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('Pesanan tidak ditemukan.');}$items=db()->prepare('SELECT oi.*,p.image FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$items->execute([$id]);$items=$items->fetchAll();$history=db()->prepare('SELECT h.*,u.name changed_name FROM order_status_histories h LEFT JOIN users u ON u.id=h.changed_by WHERE h.order_id=? ORDER BY h.created_at DESC,h.id DESC');$history->execute([$id]);$history=$history->fetchAll();$next=['pending'=>['processing','cancelled'],'processing'=>['packed','cancelled'],'packed'=>($order['fulfillment_method']==='pickup'?['completed','cancelled']:['shipped','cancelled']),'shipped'=>['completed'],'completed'=>[],'cancelled'=>[]][$order['order_status']]??[];$pageTitle='Detail Pesanan';require APP_ROOT.'/includes/admin-header.php';
