6 class="fw-bold mb-1"><?= e($order['buyer_name']) ?></h6><div><?= e($order['email']) ?></div></div><div class="col-md-6"><small class="text-muted">Penerima</small><h6 class="fw-bold mb-1"><?= e($order['recipient_name']) ?></h6><div><?= e($order['phone']) ?></div><div class="mt-2"><?= e($order['full_address']) ?></div><div class="small text-muted mt-2">Jarak dari toko: <strong><?= number_format((float) $order['delivery_distance_km'], 2, ',', '.') ?> km</strong></div><a class="btn btn-sm btn-light-green mt-2" target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?= e($order['delivery_latitude'].',' . $order['delivery_longitude']) ?>"><i class="bi bi-geo-alt me-1"></i>Lihat titik pembeli</a></div></div></div></div></div><div class="col-xl-4"><div class="admin-card mb-4"><div class="admin-card-header"><strong>Status pesanan</strong></div><div class="admin-card-body"><div class="d-flex justify-content-between mb-3"><span>Pesanan</span><span class="badge text-bg-<?= status_class($order['order_status']) ?>"><?= order_status_label($order['order_status']) ?></span></div><div class="d-flex justify-content-between mb-3"><span>Pembayaran</span><span class="badge text-bg-<?= status_class($order['payment_status']) ?>"><?= payment_status_label($order['payment_status']) ?></span></div><div class="d-flex justify-content-between mb-3"><span>Layanan</span><strong><?= e(fulfillment_label($order['fulfillment_method'])) ?></strong></div><div class="d-flex justify-content-between mb-4"><span>Metode</span><strong><?= $order['fulfillment_method']==='pickup'?'COD di Toko':strtoupper($order['payment_method']) . ' Antar' ?></strong></div><?php if($next):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="status"><label class="form-label">Ubah status</label><select class="form-select mb-2" name="order_status" required><?php foreach($next as $status):?><option value="<?= $status ?>"><?= order_status_label($status) ?></option><?php endforeach;?></sele